/* global React, BU_API,
          LevelGlyph, CertBadge, TierPill, StageChip, SectionTitle */

const { useState, useMemo } = React;

// ─────────────────────────────────────────────────────────────────
// AGENT VIEW — MARKETPLACE
// Trust-first listings + the Compose Expert wizard (§7.3):
// major → concentration → L6 badges → L5 pack → match / commission.
// The marketplace is not a static catalog — every unmet request is
// a demand signal that produces a new certified asset.
// Reads window.ATP_DATA (generated by scripts/build_atp_data.py).
// ─────────────────────────────────────────────────────────────────

const MKT_GOLD = "var(--c-cert, #e8c268)";

const REQ_STATUS_META = {
  matched:    { label: "matched",    color: "var(--c-cs, #2ec4b6)" },
  gap:        { label: "gap",        color: "var(--c-visited, #fbb036)" },
  training:   { label: "training",   color: "var(--c-bridge, #7dd3fc)" },
  certifying: { label: "certifying", color: "var(--c-summit, #c5a3ff)" },
  listed:     { label: "listed",     color: "#e8c268" },
};

const PIPELINE_STAGES = ["requested", "corpus-mapped", "fine-tuning", "certifying", "listed"];

// Demo corpus mapping for the provenance-label preview when the backend is
// unreachable (the live request carries real `corpora`).
const OCW_BY_COURSE = {
  "6": ["OCW 6.1010", "OCW 6.1210"],
  "8": ["OCW 8.02", "OCW 8.03"],
  "18": ["OCW 18.03", "OCW 18.06"],
  "2": ["OCW 2.001", "OCW 2.005"],
};

function _mktCert(A, id) {
  if (!A) return null;
  try { if (typeof A.certById === "function") return A.certById(id) || null; } catch (_) {}
  return (A.CERTS || []).find(c => c.id === id) || null;
}

function _mktAgent(A, id) {
  if (!A) return null;
  try { if (typeof A.agentById === "function") return A.agentById(id) || null; } catch (_) {}
  return (A.AGENTS || []).find(a => a.id === id) || null;
}

// Local mirror of ATP_DATA.matchExperts — used only if the generated helper
// is missing, so the wizard never dead-ends. Same rule as the contract:
// exact = covers all track competencies AND holds the badge certs AND
// (packId ? bound to the pack's policies : true). Partial ranked by coverage.
function _mktLocalMatch(A, { course, concentrationId, badgeIds, packId }) {
  const major = ((A.COMPOSE || {}).majors || []).find(m => m.course === course);
  const conc = ((major || {}).concentrations || []).find(c => c.id === concentrationId);
  const comps = (conc && conc.competencies) || [];
  const pack = packId ? ((A.COMPOSE || {}).packs || []).find(p => p.id === packId) : null;
  const exact = [], partial = [];
  (A.AGENTS || []).forEach(ag => {
    const names = new Set((ag.skills || []).map(s => s.name));
    const covered = comps.filter(c => names.has(c));
    const missing = comps.filter(c => !names.has(c));
    const hasBadges = (badgeIds || []).every(b => (ag.certIds || []).includes(b));
    const hasPack = !pack || ((pack.policyIds || []).every(pid => (ag.policyIds || []).includes(pid)));
    if (comps.length && !missing.length && hasBadges && hasPack) exact.push(ag.id);
    else if (covered.length) partial.push({ agentId: ag.id, covered, missing });
  });
  partial.sort((a, b) => b.covered.length - a.covered.length);
  return { exact, partial };
}

function MktProvenanceChip({ provenance }) {
  if (!provenance || provenance.origin !== "commissioned") return null;
  return (
    <span className="tag" style={{
      color: MKT_GOLD, fontFamily: "var(--f-mono)", fontSize: 10,
      borderColor: "color-mix(in oklch, #e8c268 50%, transparent)",
    }}>
      trained-to-order · corpus: {(provenance.corpora || []).join("/")}
    </span>
  );
}

function MktStars({ rating }) {
  const full = Math.round(rating || 0);
  return (
    <span className="t-mono" style={{ fontSize: 12, color: MKT_GOLD, letterSpacing: 2 }}>
      {"★".repeat(full)}{"☆".repeat(Math.max(0, 5 - full))}
      <span style={{ color: "var(--c-ink-muted)", letterSpacing: 0, marginLeft: 6 }}>
        {(rating || 0).toFixed(1)}
      </span>
    </span>
  );
}

function MktStatusChip({ status }) {
  const m = REQ_STATUS_META[status] || { label: status, color: "var(--c-ink-muted)" };
  return (
    <span className="tag" style={{
      color: m.color, fontFamily: "var(--f-mono)", fontSize: 10,
      borderColor: `color-mix(in oklch, ${m.color} 50%, transparent)`,
    }}>{m.label}</span>
  );
}

// ── License-key clipboard (same idiom as atp-certs copy link) ────

async function mktCopyText(text) {
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      await navigator.clipboard.writeText(text);
      return true;
    }
  } catch (_) { /* fall through to execCommand */ }
  try {
    const ta = document.createElement("textarea");
    ta.value = text;
    ta.style.position = "fixed";
    ta.style.opacity = "0";
    document.body.appendChild(ta);
    ta.select();
    const ok = document.execCommand("copy");
    document.body.removeChild(ta);
    return ok;
  } catch (_) { return false; }
}

function MktCopyBtn({ text, label = "⧉ copy key" }) {
  const [state, setState] = useState("idle"); // idle | copied | failed
  return (
    <button type="button" className="btn ghost"
      title="Copy the license key to the clipboard"
      onClick={async e => {
        e.stopPropagation();
        const ok = await mktCopyText(text);
        setState(ok ? "copied" : "failed");
        setTimeout(() => setState("idle"), 1600);
      }}
      style={{
        padding: "2px 7px", fontSize: 10.5, fontFamily: "var(--f-mono)",
        flexShrink: 0, whiteSpace: "nowrap",
        color: state === "copied" ? "var(--c-cs)"
             : state === "failed" ? "var(--c-here)" : undefined,
      }}>
      {state === "copied" ? "✓ copied" : state === "failed" ? "copy failed" : label}
    </button>
  );
}

// Extract a VERBATIM error reason from a response body or thrown error —
// a revoked / invalid key must surface the server's own words, never a
// softened demo message.
function mktErrText(x) {
  if (!x) return "no response";
  if (typeof x === "string") return x;
  const s = x.status ? `${x.status} — ` : "";
  const t = x.detail || x.error || x.reason || x.message;
  if (t != null) return s + (typeof t === "string" ? t : JSON.stringify(t));
  try { return s + JSON.stringify(x); } catch (_) { return s + String(x); }
}

const mktInputStyle = {
  width: "100%", background: "var(--c-bg-elev)",
  border: "1px solid var(--c-line-strong)", borderRadius: "var(--r-md)",
  padding: "7px 9px", color: "var(--c-ink)",
  fontFamily: "var(--f-mono)", fontSize: 11.5, outline: "none",
};

// ── Try-it box — hit the licensed delivery endpoint with a key ──
// Renders only when the api client exposes expertChat (built in
// parallel — typeof-guarded). The prompt textarea appears once a key
// is present in the local input; 401/403 reasons render verbatim so
// revocation is visible at the point of use.
function MktTryIt({ agentId, tryKey, setTryKey, open, setOpen }) {
  const [prompt, setPrompt] = useState("");
  const [busy, setBusy] = useState(false);
  const [out, setOut] = useState(null); // {reply, usage} | {error}

  const api = window.BU_API;
  if (!api || typeof api.expertChat !== "function") return null;

  const key = (tryKey || "").trim();
  const canSend = Boolean(key && prompt.trim() && !busy);

  const send = async () => {
    if (!canSend) return;
    setBusy(true); setOut(null);
    let res;
    try {
      res = await api.expertChat(agentId, [{ role: "user", content: prompt.trim() }], key);
    } catch (e) {
      setBusy(false);
      setOut({ error: mktErrText(e) });
      return;
    }
    setBusy(false);
    if (res && res.ok !== false && (res.reply != null || res.content != null)) {
      setOut({ reply: res.reply != null ? res.reply : res.content, usage: res.usage || null });
    } else {
      setOut({ error: mktErrText(res) });
    }
  };

  if (!open) {
    return (
      <button className="btn ghost" style={{ fontSize: 11.5, alignSelf: "flex-start" }}
        onClick={() => setOpen(true)}>
        ▸ try it with a license key
      </button>
    );
  }

  return (
    <div className="card recessed" style={{ padding: "10px 12px", display: "flex", flexDirection: "column", gap: 8 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8 }}>
        <div className="t-tag" style={{ color: "var(--c-ink-dim)" }}>TRY IT · LICENSED DELIVERY</div>
        <button className="btn ghost" style={{ fontSize: 11, padding: "2px 7px" }}
          onClick={() => setOpen(false)}>▾ hide</button>
      </div>
      <input value={tryKey} onChange={e => setTryKey(e.target.value)}
        placeholder="paste your license key" spellCheck={false}
        style={mktInputStyle} />
      {key !== "" && (
        <React.Fragment>
          <textarea value={prompt} onChange={e => setPrompt(e.target.value)}
            placeholder="ask the expert something…"
            style={{ ...mktInputStyle, fontFamily: "var(--f-sans)", fontSize: 12.5,
                     minHeight: 52, resize: "vertical", lineHeight: 1.45 }} />
          <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
            <button className="btn primary" disabled={!canSend} onClick={send}
              style={{ opacity: canSend ? 1 : 0.5, fontSize: 12 }}>
              {busy ? "Calling…" : "Send →"}
            </button>
            <span className="t-mono" style={{ fontSize: 10, color: "var(--c-ink-dim)" }}>
              metered — every call lands in usage_events
            </span>
          </div>
        </React.Fragment>
      )}
      {out && out.error != null && (
        <div className="t-mono" style={{
          fontSize: 11.5, color: "var(--c-here)", padding: "8px 10px",
          border: "1px solid color-mix(in oklch, var(--c-here) 45%, transparent)",
          borderRadius: "var(--r-md)", whiteSpace: "pre-wrap", wordBreak: "break-word",
        }}>
          {out.error}
        </div>
      )}
      {out && out.reply != null && (
        <div style={{
          padding: "8px 10px", borderRadius: "var(--r-md)",
          border: "1px solid color-mix(in oklch, var(--c-cs, #2ec4b6) 40%, transparent)",
        }}>
          <div style={{ fontSize: 13, lineHeight: 1.5, whiteSpace: "pre-wrap" }}>{out.reply}</div>
          {out.usage && (
            <div className="t-mono" style={{ fontSize: 10.5, color: "var(--c-ink-dim)", marginTop: 6 }}>
              usage: {typeof out.usage === "object" ? JSON.stringify(out.usage) : String(out.usage)}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// ── Listing card — trust signals LEAD ───────────────────────────

function ListingCard({ A, listing, onViewAgent, matchNote }) {
  // lic.state: idle | confirm | busy | issued | forbidden | demo
  const [lic, setLic] = useState({ state: "idle" });
  const [tryOpen, setTryOpen] = useState(false);
  const [tryKey, setTryKey] = useState("");
  const agent = _mktAgent(A, listing.agentId);
  const trust = listing.trust || {};
  const certs = ((agent && agent.certIds) || []).map(id => _mktCert(A, id)).filter(Boolean);

  // Live billing = api client present + billingIssue shipped (parallel
  // builder — typeof-guarded) + a backend actually configured.
  const billingLive = () => {
    const api = window.BU_API;
    return Boolean(api && typeof api.billingIssue === "function"
      && typeof api.live === "function" && api.live());
  };

  async function issueLicense() {
    if (!billingLive()) { setLic({ state: "demo" }); return; }
    setLic({ state: "busy" });
    let res = null;
    try {
      res = await BU_API.billingIssue({ agentId: listing.agentId, kind: listing.license });
    } catch (e) {
      res = (e && e.forbidden) ? { ok: false, forbidden: true } : { ok: false, offline: true };
    }
    if (res && res.forbidden) { setLic({ state: "forbidden" }); return; }
    const key = res && res.ok !== false
      ? (res.licenseKey || res.license_key
         || (res.license && (res.license.licenseKey || res.license.key)) || null)
      : null;
    if (key) {
      setLic({ state: "issued", key });
      // Prefill the try-it box — the server never shows this key again.
      setTryKey(key);
      setTryOpen(true);
      return;
    }
    setLic({ state: "demo" }); // offline or unexpected shape — degrade to demo
  }

  return (
    <div className="card" style={{
      display: "flex", flexDirection: "column", gap: 10,
      borderTop: `2px solid ${MKT_GOLD}`,
    }}>
      {matchNote}

      {/* 1 — credentials up front */}
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
        {certs.slice(0, 4).map(c => (
          <CertBadge key={c.id} cert={c} size={34}
            onClick={() => onViewAgent && onViewAgent(listing.agentId)} />
        ))}
        {certs.length > 4 && (
          <span className="t-mono" style={{ fontSize: 10.5, color: "var(--c-ink-dim)" }}>
            +{certs.length - 4} more
          </span>
        )}
        <MktProvenanceChip provenance={agent && agent.provenance} />
      </div>

      {/* 2 — trust strip */}
      <div style={{ display: "flex", gap: 12, flexWrap: "wrap", alignItems: "center" }}>
        <span className="t-mono" style={{ fontSize: 11.5, color: MKT_GOLD, fontWeight: 600 }}>
          L{trust.certLevel != null ? trust.certLevel : (agent && agent.level)} certified
        </span>
        <span className="t-mono" style={{ fontSize: 11.5, color: "var(--c-ink-muted)" }}>
          {trust.evidenceCount != null ? trust.evidenceCount : "—"} evidence records
        </span>
        <TierPill tier={trust.tier || (agent && agent.tier)} />
      </div>
      {(trust.benchmarkTop || []).length > 0 && (
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
          {(trust.benchmarkTop || []).slice(0, 3).map((b, i) => (
            <span key={i} className="tag" style={{ fontFamily: "var(--f-mono)", fontSize: 10.5 }}>
              {b.name} · {b.score}
            </span>
          ))}
        </div>
      )}

      {/* 3 — failure modes, visible, not hidden */}
      <div className="card recessed" style={{ padding: "8px 12px" }}>
        <div className="t-tag" style={{ color: "var(--c-here)", marginBottom: 4 }}>
          KNOWN FAILURE MODES
        </div>
        {((trust.failureModes || []).length ? trust.failureModes : ["none recorded — undertested"]).map((f, i) => (
          <div key={i} className="t-cap" style={{ fontSize: 12, marginBottom: 2 }}>
            <span style={{ color: "var(--c-here)", marginRight: 5 }}>·</span>{f}
          </div>
        ))}
      </div>

      {/* 4 — then the sales part */}
      <div style={{ flex: 1 }}>
        <div className="t-h3" style={{ marginBottom: 3 }}>{listing.headline}</div>
        <div className="t-mono" style={{ fontSize: 11.5, color: "var(--c-ink-muted)" }}>
          {agent ? `${agent.emoji} ${agent.name} · ${agent.baseModel}` : listing.agentId}
        </div>
      </div>

      <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
        <span className="t-num" style={{ fontSize: 18, color: "var(--c-ink)" }}>{listing.price}</span>
        <span className="tag" style={{ fontFamily: "var(--f-mono)", fontSize: 10 }}>{listing.license}</span>
        <MktStars rating={listing.rating} />
      </div>

      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
        {lic.state === "idle" && (
          <button className="btn primary" onClick={() => setLic({ state: "confirm" })}>License</button>
        )}
        {lic.state === "confirm" && (
          <React.Fragment>
            <span className="t-cap" style={{ fontSize: 12 }}>
              Confirm {listing.license} license at {listing.price}?
            </span>
            <button className="btn primary" onClick={issueLicense}>Confirm</button>
            <button className="btn ghost" onClick={() => setLic({ state: "idle" })}>Cancel</button>
          </React.Fragment>
        )}
        {lic.state === "busy" && (
          <span className="t-mono" style={{ fontSize: 11.5, color: "var(--c-ink-muted)" }}>
            Issuing license…
          </span>
        )}
        {lic.state === "demo" && (
          <span className="tag" style={{
            color: "var(--c-cs, #2ec4b6)",
            borderColor: "color-mix(in oklch, var(--c-cs, #2ec4b6) 50%, transparent)",
          }}>Licensed ✓ (demo — backend offline)</span>
        )}
        {lic.state === "forbidden" && (
          <span className="tag" style={{
            color: "var(--c-here)",
            borderColor: "color-mix(in oklch, var(--c-here) 50%, transparent)",
          }}>issuing a license requires org admin</span>
        )}
        {lic.state === "issued" && (
          <span className="tag" style={{
            color: "var(--c-cs, #2ec4b6)",
            borderColor: "color-mix(in oklch, var(--c-cs, #2ec4b6) 50%, transparent)",
          }}>Licensed ✓</span>
        )}
        <button className="btn" onClick={() => onViewAgent && onViewAgent(listing.agentId)}>
          Full profile →
        </button>
      </div>

      {/* one-time key reveal — the server never returns this key again */}
      {lic.state === "issued" && (
        <div className="card recessed slide-up" style={{
          padding: "10px 12px", borderLeft: `3px solid ${MKT_GOLD}`,
        }}>
          <div className="t-tag" style={{ color: MKT_GOLD, marginBottom: 6 }}>
            LICENSE KEY · SHOWN ONCE
          </div>
          <div className="t-mono" style={{
            fontSize: 11, wordBreak: "break-all", userSelect: "all", marginBottom: 8,
          }}>{lic.key}</div>
          <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
            <MktCopyBtn text={lic.key} />
            <span className="t-cap" style={{ fontSize: 11, color: "var(--c-visited, #fbb036)" }}>
              store this now — not shown again
            </span>
            <a className="t-mono" href="#/governance"
              style={{ fontSize: 11, color: MKT_GOLD, textDecoration: "none" }}>
              manage in Governance →
            </a>
          </div>
        </div>
      )}

      <MktTryIt agentId={listing.agentId}
        tryKey={tryKey} setTryKey={setTryKey}
        open={tryOpen} setOpen={setTryOpen} />
    </div>
  );
}

// ── Commission pipeline (train-to-order) ────────────────────────

function CommissionPipeline({ request, onViewAgent }) {
  const stages = (request.pipeline && request.pipeline.length)
    ? request.pipeline
    : PIPELINE_STAGES.map(s => ({ stage: s, ts: null, done: false }));
  const activeIdx = stages.findIndex(s => !s.done);
  const corpora = (request.corpora || []).join("/") || "TBD";

  return (
    <div className="card recessed slide-up" style={{ padding: 18, borderLeft: `3px solid ${MKT_GOLD}` }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 8 }}>
        <div className="t-tag" style={{ color: MKT_GOLD }}>COMMISSION ACCEPTED · {request.id}</div>
        <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
          <MktStatusChip status={request.status} />
          {request.offline && (
            <span className="tag" style={{ fontFamily: "var(--f-mono)", fontSize: 10, color: "var(--c-ink-dim)" }}>
              offline demo — queued locally
            </span>
          )}
        </div>
      </div>

      {/* pipeline stepper */}
      <div style={{ display: "flex", alignItems: "flex-start", margin: "18px 0 6px", overflowX: "auto" }}>
        {stages.map((s, i) => {
          const isActive = i === activeIdx;
          const color = s.done ? "#e8c268" : (isActive ? "var(--c-bridge)" : "var(--c-ink-dim)");
          return (
            <React.Fragment key={s.stage}>
              {i > 0 && (
                <div style={{
                  flex: 1, height: 2, marginTop: 7, minWidth: 18,
                  background: s.done || isActive
                    ? "color-mix(in oklch, #e8c268 60%, transparent)"
                    : "var(--c-line)",
                }} />
              )}
              <div style={{ textAlign: "center", minWidth: 78 }}>
                <div className={isActive ? "pulse" : ""} style={{
                  width: 14, height: 14, borderRadius: "50%", margin: "0 auto",
                  background: s.done ? "#e8c268" : "transparent",
                  border: `2px solid ${color}`,
                }} />
                <div className="t-mono" style={{ fontSize: 9.5, marginTop: 6, color, whiteSpace: "nowrap" }}>
                  {s.stage}
                </div>
                {s.ts && (
                  <div className="t-mono" style={{ fontSize: 9, color: "var(--c-ink-dim)", marginTop: 2 }}>{s.ts}</div>
                )}
              </div>
            </React.Fragment>
          );
        })}
      </div>

      {/* provenance-label preview */}
      <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap", marginTop: 12 }}>
        <span className="t-cap" style={{ fontSize: 11.5, color: "var(--c-ink-dim)" }}>listing will carry:</span>
        <span className="tag" style={{
          color: MKT_GOLD, fontFamily: "var(--f-mono)", fontSize: 10,
          borderColor: "color-mix(in oklch, #e8c268 50%, transparent)",
        }}>
          trained-to-order · corpus: {corpora}
        </span>
      </div>
      <p className="t-cap" style={{ margin: "10px 0 0", fontSize: 12.5 }}>
        Certified via the <b>same exam blueprints as every ATP agent</b> — same evidence
        trail, same judge separation, no separate trust tier.
      </p>

      {request.status === "listed" && request.resultAgentId && (
        <button className="btn primary" style={{ marginTop: 12 }}
          onClick={() => onViewAgent && onViewAgent(request.resultAgentId)}>
          View the listed expert →
        </button>
      )}
    </div>
  );
}

// ── Compose Expert wizard (§7.3) ────────────────────────────────

function ComposeWizard({ A, onViewAgent, onCommissioned }) {
  const majors = (A.COMPOSE || {}).majors || [];
  const badges = (A.COMPOSE || {}).badges || [];
  const packs = (A.COMPOSE || {}).packs || [];

  const [step, setStep] = useState(0);        // 0 major · 1 conc · 2 badges · 3 pack · 4 result
  const [major, setMajor] = useState(null);
  const [conc, setConc] = useState(null);
  const [badgeIds, setBadgeIds] = useState([]);
  const [packId, setPackId] = useState(null);
  const [request, setRequest] = useState(null);
  const [busy, setBusy] = useState(false);

  const match = useMemo(() => {
    if (step < 4 || !major || !conc) return null;
    const sel = { course: major.course, concentrationId: conc.id, badgeIds, packId };
    try {
      if (typeof A.matchExperts === "function") return A.matchExperts(sel);
    } catch (_) { /* fall through to local rule */ }
    return _mktLocalMatch(A, sel);
  }, [step, major, conc, badgeIds, packId]);

  const goStep = i => { setStep(i); setRequest(null); };

  async function commission() {
    if (busy) return;
    setBusy(true);
    const payload = { major: major.course, specialty: conc.id, badgeIds, packId };
    let req = null;
    try {
      if (window.BU_API && typeof BU_API.atpCompose === "function") {
        req = await BU_API.atpCompose(payload);
      }
    } catch (_) { req = null; }
    if (!req || req.ok === false) {
      // Backend + API client both unreachable — build the same local request
      // object design/api.js would have returned (marked offline).
      const now = new Date().toISOString().slice(0, 10);
      req = {
        id: "req-local-" + Math.random().toString(36).slice(2, 7),
        ts: now, major: major.course, specialty: conc.id,
        badgeIds: [...badgeIds], packId: packId || null,
        layers: [2].concat(badgeIds.length ? [6] : []).concat(packId ? [5] : []),
        corpora: OCW_BY_COURSE[major.course] || [],
        status: "training", matchedAgentId: null, gap: null,
        pipeline: PIPELINE_STAGES.map((stage, i) => ({ stage, ts: i < 2 ? now : null, done: i < 2 })),
        resultAgentId: null, offline: true,
      };
    }
    if (!req.corpora || !req.corpora.length) req.corpora = OCW_BY_COURSE[major.course] || [];
    setRequest(req);
    setBusy(false);
    if (onCommissioned) onCommissioned(req);
  }

  // stepper header
  const stepDefs = [
    { label: "Major", value: major ? `Course ${major.course} · ${major.name}` : null },
    { label: "Concentration", value: conc ? conc.name : null },
    { label: "L6 badges", value: step > 2 ? (badgeIds.length ? `${badgeIds.length} selected` : "none") : null },
    { label: "L5 pack", value: step > 3 ? (packId ? ((packs.find(p => p.id === packId) || {}).name || packId) : "skipped") : null },
  ];

  const pickCard = (active) => ({
    cursor: "pointer", padding: 14,
    border: `1px solid ${active ? MKT_GOLD : "var(--c-line-strong)"}`,
    borderRadius: "var(--r-md)", background: active
      ? "color-mix(in oklch, #e8c268 8%, transparent)" : "var(--c-bg-elev)",
  });

  return (
    <div className="card" style={{ borderTop: `2px solid ${MKT_GOLD}`, marginBottom: 28 }}>
      <SectionTitle kicker="TRAIN-TO-ORDER" title="Compose an expert" />
      <p className="t-cap" style={{ margin: "6px 0 14px", maxWidth: 620 }}>
        Pick a major, a concentration, domain badges and an optional company pack.
        If the expert exists, license it today — if not, commission it and ATP trains
        and certifies one against the same blueprints.
      </p>

      {/* stepper */}
      <div style={{ display: "flex", gap: 4, flexWrap: "wrap", marginBottom: 16 }}>
        {stepDefs.map((sd, i) => {
          const reachable = i < step;
          const isHere = i === Math.min(step, 3) && step < 4;
          return (
            <button key={sd.label} className="btn ghost"
              onClick={() => reachable && goStep(i)}
              style={{
                fontSize: 11.5, padding: "4px 10px",
                cursor: reachable ? "pointer" : "default",
                color: isHere ? MKT_GOLD : (sd.value ? "var(--c-ink)" : "var(--c-ink-dim)"),
              }}>
              <span className="t-mono" style={{ marginRight: 6 }}>{["①", "②", "③", "④"][i]}</span>
              {sd.label}{sd.value ? `: ${sd.value}` : ""}
              {i < 3 && <span style={{ margin: "0 2px 0 10px", color: "var(--c-ink-dim)" }}>→</span>}
            </button>
          );
        })}
      </div>

      {/* step bodies */}
      {step === 0 && (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: 10 }}>
          {majors.map(m => (
            <div key={m.course} style={pickCard(major && major.course === m.course)}
              onClick={() => { setMajor(m); setConc(null); setStep(1); }}>
              <div className="t-mono" style={{ fontSize: 11, color: MKT_GOLD }}>COURSE {m.course}</div>
              <div style={{ fontWeight: 600, fontSize: 14.5, margin: "3px 0" }}>{m.name}</div>
              <div className="t-cap" style={{ fontSize: 11.5 }}>
                {(m.concentrations || []).length} concentration{(m.concentrations || []).length === 1 ? "" : "s"}
              </div>
            </div>
          ))}
          {majors.length === 0 && <div className="t-cap">No majors in the compose catalog.</div>}
        </div>
      )}

      {step === 1 && major && (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(240px, 1fr))", gap: 10 }}>
          {(major.concentrations || []).map(c => (
            <div key={c.id} style={pickCard(conc && conc.id === c.id)}
              onClick={() => { setConc(c); setStep(2); }}>
              <div style={{ fontWeight: 600, fontSize: 14.5 }}>{c.name}</div>
              <div className="t-cap" style={{ fontSize: 11.5, margin: "4px 0 8px" }}>
                {(c.competencies || []).length} competencies · graded by{" "}
                {(c.certIds || []).map(id => (_mktCert(A, id) || { label: id }).label).join(", ") || "—"}
              </div>
              <div style={{ display: "flex", gap: 4, flexWrap: "wrap" }}>
                {(c.competencies || []).slice(0, 4).map(cp => (
                  <span key={cp} className="tag" style={{ fontSize: 10 }}>{cp}</span>
                ))}
                {(c.competencies || []).length > 4 && (
                  <span className="t-mono" style={{ fontSize: 10, color: "var(--c-ink-dim)" }}>
                    +{(c.competencies || []).length - 4}
                  </span>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      {step === 2 && (
        <div>
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 14 }}>
            {badges.map(b => {
              const on = badgeIds.includes(b.certId);
              const cert = _mktCert(A, b.certId);
              return (
                <button key={b.certId} className="btn"
                  onClick={() => setBadgeIds(on ? badgeIds.filter(x => x !== b.certId) : [...badgeIds, b.certId])}
                  style={{
                    borderColor: on ? MKT_GOLD : "var(--c-line-strong)",
                    background: on ? "color-mix(in oklch, #e8c268 10%, transparent)" : "transparent",
                    fontFamily: "var(--f-mono)", fontSize: 12,
                  }}>
                  {on ? "✓ " : ""}{b.domain}
                  <span style={{ color: "var(--c-ink-dim)", marginLeft: 6, fontSize: 10 }}>
                    {cert ? cert.label : b.certId}
                  </span>
                </button>
              );
            })}
          </div>
          <button className="btn primary" onClick={() => setStep(3)}>
            Continue{badgeIds.length ? ` with ${badgeIds.length} badge${badgeIds.length === 1 ? "" : "s"}` : " without badges"} →
          </button>
        </div>
      )}

      {step === 3 && (
        <div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))", gap: 10, marginBottom: 14 }}>
            {packs.map(p => (
              <div key={p.id} style={pickCard(packId === p.id)}
                onClick={() => setPackId(packId === p.id ? null : p.id)}>
                <div style={{ fontWeight: 600, fontSize: 14 }}>{packId === p.id ? "✓ " : ""}{p.name}</div>
                <div className="t-cap" style={{ fontSize: 11.5, marginTop: 3 }}>{p.summary}</div>
              </div>
            ))}
            {packs.length === 0 && <div className="t-cap">No company packs available.</div>}
          </div>
          <div style={{ display: "flex", gap: 8 }}>
            <button className="btn primary" onClick={() => setStep(4)}>
              {packId ? "See the match →" : "Continue →"}
            </button>
            {!packId && (
              <button className="btn ghost" onClick={() => { setPackId(null); setStep(4); }}>
                Skip — no company pack
              </button>
            )}
          </div>
        </div>
      )}

      {step === 4 && (
        request ? (
          <CommissionPipeline request={request} onViewAgent={onViewAgent} />
        ) : (
          <WizardResult A={A} match={match} conc={conc}
            onViewAgent={onViewAgent} onCommission={commission} busy={busy} />
        )
      )}
    </div>
  );
}

function WizardResult({ A, match, conc, onViewAgent, onCommission, busy }) {
  if (!match) return null;
  const exactId = (match.exact || [])[0];

  // EXACT — the expert already exists: trust-first listing card + License.
  if (exactId) {
    const listing = (((A.MARKETPLACE || {}).listings) || []).find(l => l.agentId === exactId);
    const agent = _mktAgent(A, exactId);
    const note = (
      <div className="t-tag" style={{ color: "var(--c-cs, #2ec4b6)", marginBottom: 2 }}>
        ● EXACT MATCH — ALREADY CERTIFIED FOR THIS COMPOSITION
      </div>
    );
    if (listing) {
      return (
        <div className="slide-up" style={{ maxWidth: 460 }}>
          <ListingCard A={A} listing={listing} onViewAgent={onViewAgent} matchNote={note} />
        </div>
      );
    }
    return (
      <div className="card recessed slide-up" style={{ padding: 16 }}>
        {note}
        <div style={{ fontWeight: 600, fontSize: 15, margin: "6px 0" }}>
          {agent ? `${agent.emoji} ${agent.name}` : exactId}
        </div>
        <button className="btn primary" onClick={() => onViewAgent && onViewAgent(exactId)}>
          Full profile →
        </button>
      </div>
    );
  }

  // PARTIAL — gap analysis: covered vs missing, ranked partial agents.
  if ((match.partial || []).length) {
    const best = match.partial[0];
    const total = best.covered.length + best.missing.length;
    return (
      <div className="card recessed slide-up" style={{ padding: 16, borderLeft: "3px solid var(--c-visited)" }}>
        <div className="t-tag" style={{ color: "var(--c-visited)", marginBottom: 8 }}>
          ◐ PARTIAL MATCH — GAP ANALYSIS
        </div>
        <div style={{ display: "flex", gap: 16, flexWrap: "wrap", marginBottom: 12 }}>
          <span className="t-mono" style={{ fontSize: 12, color: "var(--c-cs, #2ec4b6)" }}>
            {best.covered.length}/{total} competencies covered
          </span>
          <span className="t-mono" style={{ fontSize: 12, color: "var(--c-here)" }}>
            {best.missing.length} missing
          </span>
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: 14, marginBottom: 14 }}>
          <div>
            <div className="t-tag" style={{ color: "var(--c-cs, #2ec4b6)", marginBottom: 5 }}>COVERED</div>
            {best.covered.map(c => (
              <div key={c} className="t-cap" style={{ fontSize: 12.5, marginBottom: 3, color: "var(--c-ink)" }}>
                <span style={{ color: "var(--c-cs, #2ec4b6)", marginRight: 6 }}>✓</span>{c}
              </div>
            ))}
          </div>
          <div>
            <div className="t-tag" style={{ color: "var(--c-here)", marginBottom: 5 }}>MISSING</div>
            {best.missing.map(c => (
              <div key={c} className="t-cap" style={{ fontSize: 12.5, marginBottom: 3, color: "var(--c-ink)" }}>
                <span style={{ color: "var(--c-here)", marginRight: 6 }}>✕</span>{c}
              </div>
            ))}
          </div>
        </div>

        <div className="t-tag" style={{ color: "var(--c-ink-muted)", marginBottom: 6 }}>
          BEST PARTIAL AGENTS · RANKED BY COVERAGE
        </div>
        {match.partial.slice(0, 3).map(p => {
          const ag = _mktAgent(A, p.agentId);
          const tot = p.covered.length + p.missing.length || 1;
          return (
            <div key={p.agentId} style={{ display: "flex", alignItems: "center", gap: 10, padding: "6px 0", borderBottom: "1px solid var(--c-line)" }}>
              <span style={{ fontSize: 16 }}>{ag ? ag.emoji : "·"}</span>
              <span style={{ fontWeight: 600, fontSize: 13, minWidth: 120 }}>{ag ? ag.name : p.agentId}</span>
              {ag && <LevelGlyph n={ag.level} size={15} />}
              <div style={{ flex: 1, height: 5, borderRadius: 3, background: "var(--c-bg-elev-2)", overflow: "hidden" }}>
                <div style={{ width: `${(p.covered.length / tot) * 100}%`, height: "100%", background: "var(--c-cs, #2ec4b6)" }} />
              </div>
              <span className="t-mono" style={{ fontSize: 11, color: "var(--c-ink-muted)" }}>
                {p.covered.length}/{tot}
              </span>
            </div>
          );
        })}
        <button className="btn primary" style={{ marginTop: 14 }} onClick={onCommission} disabled={busy}>
          {busy ? "Commissioning…" : "Commission the gap →"}
        </button>
      </div>
    );
  }

  // NONE — pure demand signal.
  return (
    <div className="card recessed slide-up" style={{ padding: 16, borderLeft: "3px solid var(--c-here)" }}>
      <div className="t-tag" style={{ color: "var(--c-here)", marginBottom: 6 }}>○ NO MATCH</div>
      <p style={{ margin: "0 0 12px", fontSize: 14, lineHeight: 1.55 }}>
        No certified agent covers <b>{conc ? conc.name : "this composition"}</b> yet.
        Your request is a demand signal — ATP will map the corpus, fine-tune, and certify
        a new expert against the same blueprints.
      </p>
      <button className="btn primary" onClick={onCommission} disabled={busy}>
        {busy ? "Commissioning…" : "Commission training →"}
      </button>
    </div>
  );
}

// ── Commissions board ───────────────────────────────────────────

function CommissionsBoard({ A, extraRequests, onViewAgent }) {
  const requests = [...(extraRequests || []), ...(A.EXPERT_REQUESTS || [])];
  if (!requests.length) return null;
  return (
    <div style={{ marginTop: 36 }}>
      <SectionTitle kicker="DEMAND SIGNALS" title="Commissions board" />
      <p className="t-cap" style={{ margin: "6px 0 12px" }}>
        Every unmet request becomes a training run. Track them from request to listing.
      </p>
      <div className="card" style={{ padding: 0, overflow: "hidden" }}>
        <div style={{ overflowX: "auto" }}>
          {requests.map(r => {
            const stages = (r.pipeline && r.pipeline.length)
              ? r.pipeline
              : PIPELINE_STAGES.map(s => ({ stage: s, done: false }));
            return (
              <div key={r.id} style={{
                display: "grid",
                gridTemplateColumns: "minmax(110px, auto) 1fr auto auto auto",
                gap: 14, alignItems: "center", padding: "12px 16px",
                borderBottom: "1px solid var(--c-line)", minWidth: 640,
              }}>
                <div>
                  <div className="t-mono" style={{ fontSize: 11.5, fontWeight: 600 }}>{r.id}</div>
                  <div className="t-mono" style={{ fontSize: 10, color: "var(--c-ink-dim)", marginTop: 2 }}>{r.ts}</div>
                </div>
                <div style={{ minWidth: 0 }}>
                  <div style={{ fontSize: 13, fontWeight: 600 }}>
                    Course {r.major} · {r.specialty}
                  </div>
                  <div className="t-cap" style={{ fontSize: 11, marginTop: 2 }}>
                    {(r.badgeIds || []).length} badge{(r.badgeIds || []).length === 1 ? "" : "s"}
                    {r.packId ? ` · pack ${r.packId}` : ""}
                    {(r.corpora || []).length ? ` · ${(r.corpora || []).join(" / ")}` : ""}
                  </div>
                </div>
                <div style={{ display: "flex", gap: 4 }} title={stages.map(s => `${s.stage}${s.done ? " ✓" : ""}`).join(" → ")}>
                  {stages.map(s => (
                    <span key={s.stage} style={{
                      width: 8, height: 8, borderRadius: "50%",
                      background: s.done ? "#e8c268" : "transparent",
                      border: `1.5px solid ${s.done ? "#e8c268" : "var(--c-ink-dim)"}`,
                    }} />
                  ))}
                </div>
                <MktStatusChip status={r.status} />
                {r.status === "listed" && r.resultAgentId ? (
                  <button className="btn ghost" style={{ fontSize: 12 }}
                    onClick={() => onViewAgent && onViewAgent(r.resultAgentId)}>
                    View agent →
                  </button>
                ) : <span />}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

// ── Screen ──────────────────────────────────────────────────────

function ATPMarketplace({ onViewAgent }) {
  const A = window.ATP_DATA;
  const listings = ((A && A.MARKETPLACE && A.MARKETPLACE.listings) || []);

  const [minLevel, setMinLevel] = useState(0);
  const [domain, setDomain] = useState("all");
  const [tier, setTier] = useState("all");
  const [localReqs, setLocalReqs] = useState([]);

  const domains = useMemo(() => {
    const s = new Set();
    listings.forEach(l => {
      const ag = _mktAgent(A, l.agentId);
      (ag && ag.domains || []).forEach(d => s.add(d));
    });
    return Array.from(s).sort();
  }, [listings]);

  const filtered = useMemo(() => listings.filter(l => {
    const ag = _mktAgent(A, l.agentId);
    const lvl = (l.trust && l.trust.certLevel) != null ? l.trust.certLevel : (ag ? ag.level : 0);
    if (lvl < minLevel) return false;
    if (domain !== "all" && !((ag && ag.domains) || []).includes(domain)) return false;
    if (tier !== "all" && ((l.trust && l.trust.tier) || (ag && ag.tier)) !== tier) return false;
    return true;
  }), [listings, minLevel, domain, tier]);

  if (!A) {
    return (
      <div style={{ minHeight: "calc(100vh - 56px)", display: "grid", placeItems: "center", padding: 24 }}>
        <div className="card" style={{ maxWidth: 480, textAlign: "center" }}>
          <div className="t-h2" style={{ marginBottom: 8 }}>ATP data not loaded</div>
          <p className="t-cap">
            Run <code>python3 scripts/build_atp_data.py</code> to generate{" "}
            <code>design/atp_data.js</code>, then reload.
          </p>
        </div>
      </div>
    );
  }

  const selStyle = {
    background: "var(--c-bg-elev)", border: "1px solid var(--c-line-strong)",
    borderRadius: "var(--r-md)", color: "var(--c-ink)", padding: "6px 10px",
    fontFamily: "var(--f-mono)", fontSize: 12, outline: "none",
  };

  return (
    <div style={{ minHeight: "calc(100vh - 56px)", padding: "32px 28px 80px" }}>
      <div style={{ maxWidth: 1240, margin: "0 auto" }}>
        <SectionTitle kicker="ATP MARKETPLACE" title="License a certified agent" />
        <p className="t-cap" style={{ margin: "6px 0 24px", maxWidth: 640 }}>
          Trust signals first — certifications, evidence counts, benchmarks, and published
          failure modes — before the price tag. Can't find the expert? Compose one below
          and ATP trains it to order.
        </p>

        <ComposeWizard A={A} onViewAgent={onViewAgent}
          onCommissioned={req => setLocalReqs(prev => [req, ...prev])} />

        {/* filter bar */}
        <div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap", marginBottom: 14 }}>
          <span className="t-tag" style={{ color: "var(--c-ink-muted)" }}>LISTINGS · {filtered.length}</span>
          <select value={minLevel} onChange={e => setMinLevel(Number(e.target.value))} style={selStyle}>
            <option value={0}>min level · any</option>
            {[1, 2, 3, 4, 5, 6, 7].map(n => <option key={n} value={n}>min level · L{n}</option>)}
          </select>
          <select value={domain} onChange={e => setDomain(e.target.value)} style={selStyle}>
            <option value="all">domain · all</option>
            {domains.map(d => <option key={d} value={d}>domain · {d}</option>)}
          </select>
          <select value={tier} onChange={e => setTier(e.target.value)} style={selStyle}>
            <option value="all">tier · all</option>
            {["observer", "recommender", "executor"].map(t => <option key={t} value={t}>tier · {t}</option>)}
          </select>
          {(minLevel > 0 || domain !== "all" || tier !== "all") && (
            <button className="btn ghost" style={{ fontSize: 12 }}
              onClick={() => { setMinLevel(0); setDomain("all"); setTier("all"); }}>
              Reset filters
            </button>
          )}
        </div>

        {/* listings */}
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(330px, 1fr))", gap: 14 }}>
          {filtered.map(l => (
            <ListingCard key={l.agentId} A={A} listing={l} onViewAgent={onViewAgent} />
          ))}
        </div>
        {filtered.length === 0 && (
          <div className="card" style={{
            border: "1px dashed var(--c-line-strong)", background: "transparent",
            textAlign: "center", padding: 32,
          }}>
            <div className="t-h3" style={{ marginBottom: 6 }}>No listed agents match these filters.</div>
            <p className="t-cap" style={{ margin: "0 0 12px" }}>
              Every unmet request is a demand signal — compose the expert you need above
              and ATP will train and certify it.
            </p>
            <button className="btn" onClick={() => { setMinLevel(0); setDomain("all"); setTier("all"); }}>
              Reset filters
            </button>
          </div>
        )}

        <CommissionsBoard A={A} extraRequests={localReqs} onViewAgent={onViewAgent} />
      </div>
    </div>
  );
}

Object.assign(window, { ATPMarketplace });
